let products=[], merchandising=[];
let cart=JSON.parse(localStorage.getItem('fm-cart')||'[]'), filter='All', query='';
let session=null, authNotice='', authMode='login';
function esc(s){return String(s==null?'':s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
function isSignedIn(){return !!(session&&session.id)}
const HOUSE_CATS=['Clothes','Native wear','Shoes','Watches','Jewelry','Bags','Accessories','Other'];
function captionForCategory(cat){const c=String(cat||'').toLowerCase();if(/watch/.test(c))return 'Precision timekeeping, composed for the African evening.';if(/shoe|footwear/.test(c))return 'Crafted last and leather, made to travel the city.';if(/jewel/.test(c))return 'Quiet brilliance in metal and stone.';if(/bag/.test(c))return 'A considered companion in structured leather.';if(/accessor/.test(c))return 'The finishing note — considered, not loud.';if(/native/.test(c))return 'Heritage tailoring, cut for now.';return 'A house silhouette, cut with restraint.';}
function displayCaption(p){const own=String((p&&(p.caption||(p.attributes&&(p.attributes.caption||p.attributes.short_caption))))||'').trim();return own||captionForCategory(p&&p.cat)}
function categoryFields(cat){const c=String(cat||'').toLowerCase();if(/watch/.test(c))return [['brand','Brand'],['model','Model'],['movement','Movement / type'],['material','Material'],['strap','Strap'],['dimensions','Dimensions']];if(/shoe/.test(c))return [['material','Material'],['style','Style'],['fit','Fit']];if(/jewel/.test(c))return [['material','Material'],['stone','Stone / gem'],['dimensions','Dimensions'],['finish','Colour / finish']];if(/bag/.test(c))return [['material','Material'],['style','Style']];if(/accessor/.test(c))return [['material','Material'],['style','Style']];if(/native/.test(c))return [['material','Material'],['fit','Fit / style'],['care','Care']];return [['material','Material'],['fit','Fit / style'],['care','Care']]}
function purchaseFlags(p){const a=(p&&p.attributes&&typeof p.attributes==='object')?p.attributes:{};const status=String((p&&p.status)||'AVAILABLE');const closed=!!(p&&p.pre_order_closes_at&&!isNaN(Date.parse(p.pre_order_closes_at))&&Date.parse(p.pre_order_closes_at)<Date.now());let pre=p&&(p.pre_order_enabled===true||p.pre_order_enabled==='true'||a.pre_order_enabled===true||status==='PRE-ORDER'||p.product_type==='pre_order'||p.product_type==='made_to_order');if(closed)pre=false;let ord=!(p&&(p.order_enabled===false||p.order_enabled==='false'||a.order_enabled===false));if(status==='OUT OF STOCK')ord=false;if(status==='PRE-ORDER'&&p&&p.order_enabled==null&&a.order_enabled==null)ord=false;return {order:!!ord,preorder:!!pre,unavailable:!ord&&!pre}}
function unitPrice(p,pre){if(pre&&p&&p.pre_order_price)return Number(p.pre_order_price);return Number((p&&p.price)||0)}
function itemKey(i){return i&&i.key?i.key:String(i&&i.id||'')}
function makeKey(id,size,color,pre){return [id,size||'',color||'',pre?'1':'0'].join('|')}
function selChoice(el){if(!el||!el.parentNode)return;el.parentNode.querySelectorAll('.choice').forEach(x=>x.classList.remove('sel'));el.classList.add('sel')}
function selectedChoice(kind){const el=document.querySelector('.choices[data-kind="'+kind+'"] .choice.sel');return el?el.getAttribute('data-val')||el.textContent:''}
function findVariant(p,size,color){const list=(p&&p.variants)||[];return list.find(v=>(!size||v.size===size)&&(!color||v.color===color))||list.find(v=>v.size===size)||list.find(v=>v.color===color)||null}
function statusLabel(s){const m={pending:'Awaiting payment',pending_manual_verification:'Payment submitted — awaiting verification',paid:'Payment verified',processing:'Processing','pre-order':'Pre-order — awaiting product',ready:'Ready for fulfilment',shipped:'Shipped',delivered:'Completed',cancelled:'Cancelled',successful:'Verified',awaiting_verification:'Awaiting admin verification',rejected:'Payment needs attention',failed:'Payment failed'};return m[s]||s||''}
function fmtDate(d){if(!d)return '';const t=new Date(d);return isNaN(t)?String(d):t.toLocaleDateString('en-NG',{day:'numeric',month:'short',year:'numeric'})}
function needsAccount(){return !!(window.FashionMaisonSupabase&&FashionMaisonSupabase.configured&&!isSignedIn())}
function gateAdd(id,mode){sessionStorage.setItem('fm-pending-add',String(id));if(mode)sessionStorage.setItem('fm-pending-mode',mode);authNotice='Create an account or sign in to continue.';if((location.hash||'')!=='#/account'&&(location.hash||'')!=='#/login')location.hash='#/account';render()}
function attrLines(p){const a=(p&&p.attributes)||{};const fields=categoryFields(p&&p.cat);const rows=fields.map(([k,l])=>{const v=k==='brand'?(p.brand||a.brand):a[k];return v?`<div class="attr-row"><span>${esc(l)}</span><b>${esc(v)}</b></div>`:''}).filter(Boolean);return rows.length?`<div class="attr-grid">${rows.join('')}</div>`:''}
if(location.hash.includes('?cat='))filter=decodeURIComponent(location.hash.split('?cat=')[1]);
// FX is supplied by the server/Edge Function and cached in Supabase; never a merchant-editable product field.
const fx=()=>{const r=Number(window.FM_FX_RATE||localStorage.getItem('fm-fx-rate'));return Number.isFinite(r)&&r>0?r:null};
const money=n=>'₦'+n.toLocaleString('en-NG');
const usd=n=>fx()?`<span class=\"usd\">≈ $${(n/fx()).toFixed(2)} USD</span>`:`<span class=\"usd unavailable\">USD price temporarily unavailable</span>`;
const fxnote=()=>fx()?`<small class=\"fxnote\">1 USD ≈ ${money(fx())}. USD prices are approximate equivalents based on the latest available rate. Final payment is in Nigerian Naira.</small>`:''; const save=()=>localStorage.setItem('fm-cart',JSON.stringify(cart));
function cssBg(src){if(!src)return 'none';const safe=String(src).replace(/\\/g,'\\\\').replace(/"/g,'\\"');return `url("${safe}")`}
function catalogImageUrls(row){const raw=row&&row.product_images;const list=Array.isArray(raw)?raw.slice():(raw&&typeof raw==='object'?[raw]:[]);list.sort((a,b)=>(Number(a&&a.sort_order)||0)-(Number(b&&b.sort_order)||0));const sb=window.FashionMaisonSupabase;return list.map(i=>i&&(i.storage_path||i.url||i.path||i.public_url)).filter(Boolean).map(p=>sb&&sb.storagePublicUrl?sb.storagePublicUrl(p):p).filter(Boolean)}
function header(){return `<div class="top">COMPLIMENTARY DELIVERY ON ORDERS OVER ₦100,000</div><nav class="nav"><a class="logo" href="#/">Fashion Maison<small>Fashion, discovered differently.</small></a><div class="navlinks"><a href="#/shop">Shop</a><a href="#/shop?cat=New arrivals">New arrivals</a><a href="#/merchant">For your store</a></div><div class="navtools"><input class="search" placeholder="Search the collection" value="${query}" oninput="search(this.value)"><button class="icon" onclick="location.hash='#/account'">♙</button><button class="icon" onclick="location.hash='#/cart'">♧<sup class="cartdot">${cart.reduce((a,b)=>a+b.qty,0)}</sup></button></div></nav>`}
function card(p){const flags=purchaseFlags(p);const addBtn=flags.unavailable?`<button class="add" disabled title="Unavailable">×</button>`:`<button class="add" title="${flags.preorder&&!flags.order?'Pre-order':'Add to bag'}" onclick="add('${p.id}')">＋</button>`;return `<article class="product"><div class="productimg" style="background-image:${cssBg(p.img)}" onclick="location.hash='#/product/${p.id}'"><span class="badge">${esc(flags.unavailable?'UNAVAILABLE':(p.status||'AVAILABLE'))}</span></div><div class="productinfo">${addBtn}<div class="productname">${esc(p.name)}</div><div class="productcaption">${esc(displayCaption(p))}</div><div class="price">${money(p.price)}<br>${usd(p.price)}</div><div class="meta">${esc(p.cat)} · ${esc((p.sizes&&p.sizes.join(' / '))||'One size')}</div></div></article>`}
function categoryDiscovery(){const groups=[['Clothing',/dress|shirt|jacket|trouser|clothing/i],['Native wear',/native|agbada|senator|ankara|kaftan/i],['Watches',/watch|time|chronograph/i],['Bags',/bag|tote|crossbody|leather/i],['Shoes',/shoe|sneaker|loafer|boot|slide/i],['Jewelry',/jewel|ring|chain|bracelet|necklace/i],['Accessories',/accessor|sunglass|belt|wallet|cap/i]];const found=groups.map(g=>({name:g[0],p:products.find(p=>g[1].test((p.cat||'')+' '+(p.name||'')+' '+(p.desc||'')))})).filter(x=>x.p);if(!found.length)return '';return `<section class="wrap section category-discovery reveal"><div class="sectionhead"><div><div class="eyebrow">Explore the house</div><h2>Find your point of view.</h2></div><a href="#/shop" class="muted">Shop all →</a></div><div class="category-rail">${found.map(x=>`<a class="category-tile" href="#/product/${x.p.id}" style="background-image:${cssBg(x.p.img)}"><span>${x.name}</span></a>`).join('')}</div></section>`}
function signature(){const hero=merchandising.find(x=>x.section_key==='hero');const p=products.find(x=>x.id===hero?.hero_product_id)||products[0];if(!p)return '';return `<section class="signature wrap reveal"><div class="signature-image" style="background-image:${cssBg(p.img)}"></div><div class="signature-copy"><div class="eyebrow">Signature pieces</div><h2 class="serif">Made to be<br>noticed.</h2><p class="muted">${p.name}</p><a class="btn light" href="#/product/${p.id}">Discover</a></div></section>`}
function menEditorial(){const groups=[['THE WATCH EDIT',/watch|time|chronograph/i,'TIME, WELL SPENT.','Precision, presence and African sophistication.'],['THE LEATHER EDIT',/leather|wallet|belt|bag|card/i,'OBJECTS WITH CHARACTER.','Made for the city, considered for every day.'],['STREET, REDEFINED',/shoe|sneaker|cap|sunglass|bracelet|chain|accessor/i,'THE NEW AFRICAN COOL.','Style inspired by movement, music and modern life.'],['NATIVE / AFROPOP',/native|agbada|senator|ankara|kaftan|afropop|african/i,'ROOTED IN CULTURE. MADE FOR NOW.','Contemporary silhouettes with a sense of place.']];return groups.map((g,index)=>{const config=merchandising.find(x=>x.section_key===(['watch','leather','street','native'][index]));const list=(config?.product_ids?.length?config.product_ids.map(id=>products.find(p=>p.id===id)).filter(Boolean):products.filter(p=>g[1].test((p.cat||'')+' '+(p.name||'')+' '+(p.desc||'')))).slice(0,5);if(config&&!config.enabled)return '';if(!list.length)return '';const lead=list[0];return `<section class="wrap section men-story reveal"><div class="story-feature"><div class="story-image" style="background-image:${cssBg(lead.img)}"></div><div class="story-copy"><div class="eyebrow">Fashion Maison / ${String(index+1).padStart(2,'0')}</div><h2>${g[2]}</h2><p class="muted">${g[3]}</p><a class="btn light" href="#/product/${lead.id}">Discover the edit</a></div></div><div class="sectionhead story-head"><span class="muted">${g[0]}</span><a href="#/shop" class="muted">View collection →</a></div><div class="editorial-rail">${list.map(card).join('')}</div></section>`}).join('')}
function home(){return header()+`<main><section class="wrap hero"><div><div class="eyebrow">Fashion Maison / 01</div><h1>The new<br><i>African</i><br>cool.</h1><p>Fashion, discovered differently.</p><div><button class="btn" onclick="location.hash='#/shop'">Shop now</button> <button class="btn light" onclick="document.querySelector('.signature')?.scrollIntoView({behavior:'smooth'})">Explore the collection</button></div></div><div class="heroimg"></div></section>${categoryDiscovery()}<section class="wrap section"><div class="sectionhead"><div><div class="eyebrow">Curated for you</div><h2>New arrivals</h2></div><a href="#/shop" class="muted">View all →</a></div><div class="grid">${products.slice(0,4).map(card).join('')}</div></section><section class="wrap section"><div class="banner"><div><div class="eyebrow">For independent fashion businesses</div><h2>Your store,<br>beautifully online.</h2><p class="muted">Bring the pieces in your shop to a new audience.</p><button class="btn" onclick="location.hash='#/merchant'">Create your store</button></div><div></div></div></section>${signature()}${menEditorial()}<section class="brand-moment"><div class="eyebrow">Fashion Maison</div><h2>Fashion, discovered differently.</h2><a class="btn" href="#/shop">Shop now</a></section></main>${footer()}`}
function shop(){let ps=products.filter(p=>(filter==='All'||p.cat===filter||p.name.toLowerCase().includes(filter.toLowerCase()))&&(p.name+' '+p.cat+' '+p.desc).toLowerCase().includes(query.toLowerCase()));let cats=['All',...new Set(products.map(p=>p.cat))];return header()+`<main class="wrap section"><div class="sectionhead"><div><div class="eyebrow">The collection</div><h2>Shop all pieces</h2><p class="muted">${ps.length} pieces from Maison Lagos</p></div></div><div class="filters">${cats.map(c=>`<button class="pill ${filter===c?'active':''}" onclick="setFilter('${c}')">${c}</button>`).join('')}</div><div class="grid">${ps.length?ps.map(card).join(''):`<div class="empty">No pieces found.<br><button class="btn light" onclick="clearSearch()">Clear search</button></div>`}</div></main>${footer()}`}
function product(id){let p=products.find(x=>x.id==id);if(!p)return header()+'<div class="empty"><h2>Piece not found</h2></div>';const gallery=(p.imgs&&p.imgs.length?p.imgs:[p.img]).filter(Boolean);const g0=gallery[0]||'';const g1=gallery[1]||gallery[0]||'';const flags=purchaseFlags(p);const sizes=(p.sizes&&p.sizes.length)?p.sizes:['One size'];const colors=(p.colors&&p.colors.length)?p.colors:['House default'];const prePrice=p.pre_order_price?`<div class="price">Pre-order ${money(p.pre_order_price)}<br>${usd(p.pre_order_price)}</div>`:'';const when=p.expected_availability?`Expected ${fmtDate(p.expected_availability)}`:(flags.preorder?'Expected availability to be confirmed':'Ships from Lagos · Ready in 1–3 days');const notes=p.pre_order_notes?`<p class="muted">${esc(p.pre_order_notes)}</p>`:'';let actions='';if(flags.unavailable)actions=`<button class="btn" disabled>Unavailable</button><p class="meta">This piece cannot be purchased at the moment.</p>`;else if(flags.order&&flags.preorder)actions=`<button class="btn" onclick="add('${p.id}','order')">Add to bag / Order</button> <button class="btn light" onclick="add('${p.id}','preorder')">Pre-order</button><p class="meta">Order ships from current stock. Pre-order is held until ${esc(p.expected_availability?fmtDate(p.expected_availability):'the piece is ready')}.</p>${prePrice}${notes}`;else if(flags.preorder)actions=`<button class="btn" onclick="add('${p.id}','preorder')">Pre-order</button>${prePrice}${notes}`;else actions=`<button class="btn" onclick="add('${p.id}','order')">Add to bag</button>`;const gate=needsAccount()?'<p class="meta">Sign in to add this piece to your bag — browsing stays open to everyone.</p>':'';return header()+`<main class="wrap detail"><div class="gallery"><div style="background-image:${cssBg(g0)}"></div><div style="background-image:${cssBg(g1)}"></div></div><div><div class="eyebrow">${esc(p.cat)} / Maison Lagos</div><h1>${esc(p.name)}</h1><p class="detail-caption">${esc(displayCaption(p))}</p><div class="price">${money(p.price)}<br>${usd(p.price)}</div>${p.desc?`<p class="muted" style="line-height:1.8">${p.desc}</p>`:''}${attrLines(p)}<div class="option"><label>Size</label><div class="choices" data-kind="size">${sizes.map((x,i)=>`<button class="choice ${i===0?'sel':''}" data-val="${esc(x)}" onclick="selChoice(this)">${esc(x)}</button>`).join('')}</div></div><div class="option"><label>Colour</label><div class="choices" data-kind="color">${colors.map((x,i)=>`<button class="choice ${i===0?'sel':''}" data-val="${esc(x)}" onclick="selChoice(this)">${esc(x)}</button>`).join('')}</div></div><p class="meta">${esc(when)} · ${esc(p.status||'AVAILABLE')}</p>${actions}${gate}<div class="section"><div class="eyebrow">The house</div><h3 class="serif">Maison Lagos</h3><p class="muted">Independent fashion, carefully selected. Pickup available in Victoria Island.</p></div></div></main>${footer()}`}
function cartPage(){const lines=cart.filter(i=>{const live=products.find(p=>p.id==i.id);if(!live)return true;return !purchaseFlags(live).unavailable||i.is_preorder});let total=lines.reduce((a,i)=>a+i.price*i.qty,0);return header()+`<main class="wrap cartpanel"><div class="eyebrow">Your selection</div><h1 class="serif">Shopping bag</h1>${lines.length?lines.map(i=>`<div class="row"><span><b>${esc(i.name)}</b><br><small class="muted">${money(i.price)}${i.size?' · '+esc(i.size):''}${i.color?' · '+esc(i.color):''}${i.is_preorder?' · Pre-order':(i.cat?' · '+esc(i.cat):'')}</small></span><span><button onclick="change('${itemKey(i)}',-1)">−</button> ${i.qty} <button onclick="change('${itemKey(i)}',1)">＋</button> <button onclick="removeItem('${itemKey(i)}')"> ×</button></span></div>`).join('')+`<div class="row"><b>Total</b><b>${money(total)}<br>${usd(total)}</b></div>${fxnote()}${needsAccount()?'<p class="muted">Sign in to add more pieces — your current bag is saved on this device.</p>':''}<br><button class="btn" onclick="goCheckout()">Proceed to checkout</button>`:'<div class="empty">Your bag is waiting for something special.<br><br><button class="btn" onclick="location.hash=\'#/shop\'">Discover pieces</button></div>'}</main>`}
function checkout(){if(needsAccount())return header()+`<main class="checkout"><div class="eyebrow">Almost yours</div><h1 class="serif">Checkout</h1><p class="fm-gate">Sign in to place an order. Your bag stays saved on this device.</p><button class="btn" onclick="location.hash='#/account'">Sign in</button></main>`;if(!cart.length)return header()+`<main class="checkout"><div class="empty"><h2 class="serif">Your bag is empty</h2><button class="btn" onclick="location.hash='#/shop'">Discover pieces</button></div></main>`;let total=cart.reduce((a,i)=>a+i.price*i.qty,0);return header()+`<main class="checkout"><div class="eyebrow">Almost yours</div><h1 class="serif">Checkout</h1><p id="co-status" class="muted"></p><div class="checkoutgrid"><form onsubmit="placeOrder(event)"><div class="field"><label>Full name</label><input id="co-name" required placeholder="Your full name"></div><div class="field"><label>Email</label><input id="co-email" type="email" required placeholder="you@example.com" value="${esc((session&&session.email)||'')}"></div><div class="field"><label>Phone number</label><input id="co-phone" required placeholder="0800 000 0000"></div><div class="field"><label>Delivery address</label><input id="co-line1" required placeholder="Street address"></div><div class="field"><label>City</label><input id="co-city" required placeholder="City"></div><div class="field"><label>State</label><input id="co-state" placeholder="State"></div><div class="field"><label>Delivery method</label><select id="co-delivery"><option value="store_pickup">Store pickup — Free</option><option value="local_delivery">Local delivery — ₦3,000</option><option value="nationwide_delivery">Nationwide delivery — ₦7,000</option></select></div><div class="field"><label>Payment method</label><select id="payment-method" onchange="togglePayment(this.value)"><option value="paystack">Paystack</option><option value="manual_transfer">Bank Transfer</option></select></div><div id="bank-transfer-info" class="summary hidden">Loading bank details…</div><button class="btn" type="submit">Place order & continue</button></form><aside class="summary"><b>Order summary</b>${cart.map(i=>`<div class="row"><span>${esc(i.name)} × ${i.qty}${i.is_preorder?' <small>Pre-order</small>':''}<br><small class="muted">${esc(i.size||'')} ${esc(i.color||'')}</small></span><span>${money(i.price*i.qty)}</span></div>`).join('')}<div class="row"><span>Delivery</span><span id="co-fee">—</span></div><div class="row"><b>Total</b><b>${money(total)}<br>${usd(total)}</b></div>${fxnote()}<small class="muted">You’ll continue to Paystack or bank transfer. Card details are never stored by Fashion Maison. Amounts are confirmed server-side.</small></aside></div></main>`}function payPage(orderId){return header()+`<main class="checkout"><div class="eyebrow">Bank transfer</div><h1 class="serif">Complete payment</h1><p id="pay-status" class="muted">Loading your order…</p><div id="pay-body"></div></main>`}function checkoutReturnPage(){return header()+`<main class="checkout"><div class="eyebrow">Payment</div><h1 class="serif">Confirming Paystack</h1><p id="pay-status" class="muted">Verifying your payment with Paystack. This is not based on the browser redirect alone.</p></main>`}function goCheckout(){if(needsAccount()){authNotice='Sign in to continue to checkout.';location.hash='#/account';return}location.hash='#/checkout'}
function accountPage(){return header()+`<main class="checkout"><div class="eyebrow">Your Maison account</div><h1 class="serif">Account</h1><div id="account-state" class="summary">Checking your session…</div></main>`}
function authFormHTML(){const pending=sessionStorage.getItem('fm-pending-add');const notice=authNotice||(pending?'Create an account or sign in to continue — then your piece will be added to the bag.':'');return `${notice?`<p class="fm-gate">${esc(notice)}</p>`:''}<form class="authform" onsubmit="${authMode==='signup'?'doSignUp(event)':'doSignIn(event)'}"><div class="field"><label>Email</label><input id="auth-email" type="email" required placeholder="you@example.com" autocomplete="email"></div><div class="field"><label>Password</label><input id="auth-pass" type="password" required minlength="6" placeholder="Your password"></div>${authMode==='signup'?'<div class="field"><label>Full name</label><input id="auth-name" required placeholder="Your full name"></div>':''}<button class="btn">${authMode==='signup'?'Create account':'Sign in'}</button></form><button type="button" class="btn light" onclick="fmAuthMode('${authMode==='login'?'signup':'login'}')">${authMode==='login'?'New to Fashion Maison? Create an account':'I already have an account'}</button>`}
function fmAuthMode(m){authMode=m;authNotice='';const el=document.getElementById('account-state');if(el)el.innerHTML='<h3>Welcome to Fashion Maison</h3>'+authFormHTML()}
async function doSignIn(e){e.preventDefault();const email=document.getElementById('auth-email').value.trim();const password=document.getElementById('auth-pass').value;const el=document.getElementById('account-state');try{const r=await FashionMaisonSupabase.signIn(email,password);session={id:(r.user&&r.user.id)||null,email:(r.user&&r.user.email)||email};if(!session.id){const u=await FashionMaisonSupabase.getUser();session={id:u&&u.id,email:(u&&u.email)||email}}authNotice='';await finishAuthRedirect()}catch(err){if(el)el.innerHTML='<h3>Welcome to Fashion Maison</h3><p class="fm-gate">Unable to sign in. Check your email and password.</p>'+authFormHTML()}}
async function doSignUp(e){e.preventDefault();const email=document.getElementById('auth-email').value.trim();const password=document.getElementById('auth-pass').value;const name=(document.getElementById('auth-name')&&document.getElementById('auth-name').value.trim())||'';const el=document.getElementById('account-state');try{const r=await FashionMaisonSupabase.signUp(email,password,name);if(r&&r.access_token){FashionMaisonSupabase.setSession(r.access_token);session={id:r.user&&r.user.id,email:(r.user&&r.user.email)||email};authNotice='';await finishAuthRedirect();return}authMode='login';if(el)el.innerHTML='<h3>Welcome to Fashion Maison</h3><p class="muted">Account created. Check your email to confirm, then sign in.</p>'+authFormHTML()}catch(err){if(el)el.innerHTML='<h3>Welcome to Fashion Maison</h3><p class="fm-gate">Unable to create account. Try a different email, or sign in if you already have one.</p>'+authFormHTML()}}
async function finishAuthRedirect(){const pending=sessionStorage.getItem('fm-pending-add');const mode=sessionStorage.getItem('fm-pending-mode');if(pending){sessionStorage.removeItem('fm-pending-add');sessionStorage.removeItem('fm-pending-mode');add(pending,mode||undefined);location.hash='#/cart';return}location.hash='#/account';render()}
async function fmSignOut(){try{await FashionMaisonSupabase.signOut()}catch(e){}session=null;render();location.hash='#/'}
async function initAccount(){const el=document.getElementById('account-state');if(!el)return;try{await loadSession();if(!session){el.innerHTML='<h3>Welcome to Fashion Maison</h3><p class="muted">Sign in to add pieces to your bag and view order history. Browsing the collection stays open to everyone.</p>'+authFormHTML();return}const p=await FashionMaisonSupabase.getProfile(session.id);const rows=await FashionMaisonSupabase.rest(`/rest/v1/orders?select=id,order_number,created_at,total,status,delivery_method,payments(id,status,provider,reference,rejection_reason),order_items(product_name,quantity,unit_price,is_preorder,variant_snapshot),preorders(expected_availability,status)&customer_id=eq.${encodeURIComponent(session.id)}&order=created_at.desc`);const history=(rows&&rows.length)?rows.map(o=>{const pay=Array.isArray(o.payments)?o.payments[0]:o.payments;const items=(o.order_items||[]).map(i=>`${esc(i.product_name)} × ${i.quantity}${i.is_preorder?' (pre-order)':''}`).join('<br>');const pre=Array.isArray(o.preorders)?o.preorders[0]:o.preorders;const payLabel=pay?statusLabel(pay.status)+' · '+(pay.provider==='paystack'?'Paystack':'Bank transfer'):'Pending payment';const resume=(o.status==='pending'||o.status==='pending_manual_verification'||(pay&&pay.status==='rejected'))?`<button class="pill" onclick="location.hash='#/pay/${o.id}'">Continue payment</button>`:'';return `<div class="order-card"><div class="row"><span><b>${esc(o.order_number)}</b><br><small>${fmtDate(o.created_at)} · ${esc(statusLabel(o.status))}</small></span><b>${money(Number(o.total))}</b></div><p class="muted">${items||'—'}</p><p class="meta">${esc(payLabel)}${pay&&pay.reference?' · '+esc(pay.reference):''}${pre&&pre.expected_availability?' · Expected '+fmtDate(pre.expected_availability):''}${pay&&pay.status==='awaiting_verification'?' · Awaiting admin verification':''}${pay&&pay.status==='rejected'?' · '+esc(pay.rejection_reason||'Please resubmit proof'):''}</p>${resume}</div>`}).join(''):'<p class="muted">No orders yet.</p>';el.innerHTML=`<h3>${esc((p&&p.full_name)||session.email||'')}</h3><p class="muted">${esc(session.email||'')}</p><button class="btn light" onclick="fmSignOut()">Log out</button><hr><h3>Order history</h3>${history}`;}catch(e){el.innerHTML='<h3>Welcome to Fashion Maison</h3><p class="muted">Sign in to add pieces to your bag and view order history.</p>'+authFormHTML()}}
function merchant(){return header()+`<main class="admin"><div class="eyebrow">Fashion Maison / Admin</div><h1 class="serif">Homepage merchandising</h1><p id="admin-status" class="muted">Checking admin access…</p><section class="section"><div class="stat"><b>Hero</b><div class="field"><label>Hero product</label><select id="hero-product"><option>Loading live catalog…</option></select></div><div class="field"><label>Title</label><input id="hero-title" value="The new African cool."></div><div class="field"><label>Subtitle</label><input id="hero-subtitle" value="Fashion, discovered differently."></div><button class="btn" onclick="saveHeroMerch()">Save hero</button></div></section><section class="section"><div class="sectionhead"><h2>Homepage sections</h2><span class="muted">Real published products only</span></div><div id="merch-sections" class="table">Loading…</div></section><section class="section"><div class="sectionhead"><h2>Product images & copy</h2><span class="muted">Uploads, captions, order / pre-order</span></div><div id="product-image-admin" class="table">Sign in as admin to manage images.</div></section><section class="section"><div class="sectionhead"><h2>Payment settings</h2><span class="muted">Active bank details shown at checkout — never hard-coded</span></div><div id="payment-settings-admin" class="table">Sign in as admin.</div></section><section class="section"><div class="sectionhead"><h2>Manual payments</h2><span class="muted">Verification queue</span></div><div id="manual-payments" class="table">Loading payment queue…</div></section></main>`}
async function initMerchAdmin(){const st=document.getElementById('admin-status');if(!st)return;try{const u=await FashionMaisonSupabase.getUser();if(!u){st.textContent='Please log in to manage merchandising.';return}const prof=await FashionMaisonSupabase.getProfile(u.id);if(prof?.role!=='admin'){st.textContent='Admin authorization required.';return}st.textContent='Authorized admin';const r=await FashionMaisonSupabase.rest('/rest/v1/products?select=id,name,published&published=eq.true&order=name');const sel=document.getElementById('hero-product');sel.innerHTML=(r||[]).map(p=>`<option value="${p.id}">${p.name}</option>`).join('')||'<option>No published products</option>';document.getElementById('merch-sections').innerHTML=merchGroups.map(g=>`<div class="row"><span><b>${g[1]}</b><br><small class="muted">Products and visibility</small></span><label><input type="checkbox" checked id="enabled-${g[0]}"> Enabled</label><button class="pill" onclick="saveSectionMerch('${g[0]}')">Save</button></div>`).join('');loadManualPayments();loadProductImageAdmin();loadPaymentSettingsAdmin()}catch(e){st.textContent='Unable to load admin catalog.'}}
function fmSafeImageName(name){const base=String(name||'image').split(/[/\\]/).pop();const dot=base.lastIndexOf('.');const ext=(dot>=0?base.slice(dot):'').toLowerCase();const stem=((dot>=0?base.slice(0,dot):base).replace(/[^a-zA-Z0-9._-]+/g,'-').replace(/^-+|-+$/g,'').slice(0,80))||'image';return stem+(['.jpg','.jpeg','.png','.webp'].includes(ext)?ext:'.jpg')}
async function loadProductImageAdmin(){const el=document.getElementById('product-image-admin');if(!el)return;try{const rows=await FashionMaisonSupabase.rest('/rest/v1/products?select=*,product_images(id,storage_path,sort_order),categories(name)&order=name.asc');el.innerHTML=rows&&rows.length?rows.map(p=>{const thumbs=(p.product_images||[]).slice().sort((a,b)=>(a.sort_order||0)-(b.sort_order||0)).map(img=>`<img class="fm-admin-thumb" alt="" src="${FashionMaisonSupabase.storagePublicUrl(img.storage_path)}">`).join('')||'<span class="muted">No image yet</span>';const attrs=(p.attributes&&typeof p.attributes==='object')?p.attributes:{};const cat=(p.categories&&p.categories.name)||attrs.house_category||'';const caption=attrs.caption||attrs.short_caption||'';const cats=HOUSE_CATS.includes(cat)?HOUSE_CATS:[cat,...HOUSE_CATS].filter(Boolean);const flags=purchaseFlags({status:p.status,order_enabled:p.order_enabled,pre_order_enabled:p.pre_order_enabled,product_type:p.product_type,attributes:attrs,pre_order_closes_at:p.pre_order_closes_at});const extra=categoryFields(cat).map(([k,l])=>{const val=k==='brand'?(p.brand||attrs.brand||''): (attrs[k]||'');return `<div class="field"><label>${esc(l)}</label><input id="fm-attr-${k}-${p.id}" value="${esc(val)}"></div>`}).join('');return `<div class="admin-piece"><div class="row"><span><b>${esc(p.name)}</b><br><small class="muted">${p.published?'Published':'Draft'} · ${esc(p.status||'')}</small><div class="fm-admin-thumbs">${thumbs}</div></span><span><input id="fm-img-${p.id}" type="file" accept="image/jpeg,image/png,image/webp"><button class="pill" onclick="fmAdminUploadImage('${p.id}')">Upload image</button></span></div><div class="admin-copy"><div class="field"><label>Category</label><select id="fm-cat-${p.id}" onchange="fmSuggestCaption('${p.id}')">${cats.map(c=>`<option ${c===cat?'selected':''}>${esc(c)}</option>`).join('')}</select></div><div class="field"><label>Short luxury caption</label><textarea id="fm-cap-${p.id}" rows="2">${esc(caption)}</textarea><button type="button" class="pill" onclick="fmSuggestCaption('${p.id}')">Suggest for this category</button></div><div class="field"><label>Full description</label><textarea id="fm-desc-${p.id}" rows="3">${esc(p.description||'')}</textarea></div><div class="field"><label>Price (NGN)</label><input id="fm-price-${p.id}" type="number" min="0" step="1" value="${esc(p.base_price||p.price||'')}"></div><div class="side"><label><input type="checkbox" id="fm-ord-${p.id}" ${flags.order?'checked':''}> Order enabled</label><label><input type="checkbox" id="fm-pre-${p.id}" ${flags.preorder?'checked':''}> Pre-order enabled</label></div><div class="field"><label>Availability status</label><select id="fm-status-${p.id}">${['AVAILABLE','LOW STOCK','OUT OF STOCK','PRE-ORDER'].map(s=>`<option ${s===(p.status||'AVAILABLE')?'selected':''}>${s}</option>`).join('')}</select></div><div class="field"><label>Expected availability</label><input id="fm-avail-${p.id}" type="date" value="${esc((p.expected_availability||'').toString().slice(0,10))}"></div><div class="field"><label>Pre-order price (optional)</label><input id="fm-pprice-${p.id}" type="number" min="0" step="1" value="${esc(p.pre_order_price||'')}"></div><div class="field"><label>Pre-order notes</label><textarea id="fm-pnotes-${p.id}" rows="2">${esc(p.pre_order_notes||attrs.pre_order_notes||'')}</textarea></div><div class="field"><label>Pre-order quantity limit (optional)</label><input id="fm-pmax-${p.id}" type="number" min="1" step="1" value="${esc(p.pre_order_max_qty||'')}"></div><div id="fm-extra-${p.id}">${extra}</div><button class="btn light" onclick="fmSaveProductCopy('${p.id}')">Save copy & purchasing</button></div></div>`}).join(''):'<div class="empty">No products found.</div>'}catch(e){el.textContent='Unable to load product images.'}}
function fmSuggestCaption(id){const catEl=document.getElementById('fm-cat-'+id);const capEl=document.getElementById('fm-cap-'+id);if(!capEl)return;capEl.value=captionForCategory(catEl&&catEl.value)}
async function fmSaveProductCopy(id){const st=document.getElementById('admin-status');const cap=(document.getElementById('fm-cap-'+id)||{}).value||'';const desc=(document.getElementById('fm-desc-'+id)||{}).value||'';const cat=(document.getElementById('fm-cat-'+id)||{}).value||'';const orderOn=!!(document.getElementById('fm-ord-'+id)&&document.getElementById('fm-ord-'+id).checked);const preOn=!!(document.getElementById('fm-pre-'+id)&&document.getElementById('fm-pre-'+id).checked);const status=(document.getElementById('fm-status-'+id)||{}).value||'AVAILABLE';const price=(document.getElementById('fm-price-'+id)||{}).value;const pprice=(document.getElementById('fm-pprice-'+id)||{}).value;const notes=(document.getElementById('fm-pnotes-'+id)||{}).value||'';const pmax=(document.getElementById('fm-pmax-'+id)||{}).value;const avail=(document.getElementById('fm-avail-'+id)||{}).value||null;try{if(st)st.textContent='Saving copy…';const rows=await FashionMaisonSupabase.rest(`/rest/v1/products?select=id,attributes&id=eq.${encodeURIComponent(id)}&limit=1`);const existing=(rows&&rows[0]&&rows[0].attributes&&typeof rows[0].attributes==='object')?rows[0].attributes:{};const attributes=Object.assign({},existing,{caption:String(cap).trim(),house_category:cat||existing.house_category||null,pre_order_notes:String(notes).trim()||null,order_enabled:orderOn,pre_order_enabled:preOn});categoryFields(cat).forEach(([k])=>{const el=document.getElementById('fm-attr-'+k+'-'+id);if(el)attributes[k]=el.value.trim();});if(attributes.brand){}const nextStatus=!orderOn&&!preOn?'OUT OF STOCK':(preOn&&!orderOn?'PRE-ORDER':status);const record={description:String(desc).trim()||null,attributes,status:nextStatus,expected_availability:avail||null,pre_order_notes:String(notes).trim()||null,order_enabled:orderOn,pre_order_enabled:preOn,pre_order_price:pprice===''||pprice==null?null:Number(pprice),pre_order_max_qty:pmax===''||pmax==null?null:Number(pmax)};if(price!==''&&price!=null){record.price=Number(price);record.base_price=Number(price)}const brandEl=document.getElementById('fm-attr-brand-'+id);if(brandEl)record.brand=brandEl.value.trim()||null;const slim={description:record.description,attributes:record.attributes,status:record.status,expected_availability:record.expected_availability,pre_order_price:record.pre_order_price,brand:record.brand,price:record.price,base_price:record.base_price};try{await FashionMaisonSupabase.invoke('admin-catalog',{table:'products',operation:'update',id,record})}catch(e){try{await FashionMaisonSupabase.invoke('admin-catalog',{table:'products',operation:'update',id,record:slim})}catch(e2){await FashionMaisonSupabase.rest(`/rest/v1/products?id=eq.${encodeURIComponent(id)}`,{method:'PATCH',body:JSON.stringify(slim)})}}if(st)st.textContent='Caption, description and purchasing options saved.';await loadLiveProducts();await loadProductImageAdmin()}catch(e){if(st)st.textContent='Could not save copy: '+(e.message||'try again.')}}
async function fmAdminUploadImage(productId){const input=document.getElementById('fm-img-'+productId);const file=input&&input.files&&input.files[0];const st=document.getElementById('admin-status');if(!file){if(st)st.textContent='Choose an image file first.';return}if(!/^image\/(jpeg|png|webp)$/.test(file.type)||file.size>8388608){if(st)st.textContent='Use a JPEG, PNG or WebP image up to 8MB.';return}try{if(st)st.textContent='Uploading image…';const path=`products/${productId}/${Date.now()}-${fmSafeImageName(file.name)}`;await FashionMaisonSupabase.uploadProductImage(path,file);try{await FashionMaisonSupabase.invoke('admin-catalog',{table:'product_images',operation:'insert',record:{product_id:productId,storage_path:path,sort_order:0}})}catch(e){await FashionMaisonSupabase.rest('/rest/v1/product_images',{method:'POST',body:JSON.stringify({product_id:productId,storage_path:path,sort_order:0})})}if(st)st.textContent='Image uploaded — it now appears on the storefront.';await loadLiveProducts();await loadProductImageAdmin()}catch(e){if(st)st.textContent='Image upload failed: '+(e.message||'please try again.')}}
async function loadManualPayments(){const el=document.getElementById('manual-payments');if(!el)return;try{const rows=await FashionMaisonSupabase.rest('/rest/v1/payments?select=id,reference,amount,status,provider,submitted_at,receipt_path,rejection_reason,sender_account_name,order_id,orders(order_number,status,customer_id,total,delivery_address,order_items(product_name,quantity,is_preorder))&provider=eq.manual_transfer&order=submitted_at.desc');el.innerHTML=rows&&rows.length?rows.map(p=>{const o=Array.isArray(p.orders)?p.orders[0]:p.orders;const items=((o&&o.order_items)||[]).map(i=>`${esc(i.product_name)} × ${i.quantity}${i.is_preorder?' (pre-order)':''}`).join(', ');const addr=o&&o.delivery_address;return `<div class="order-card"><div class="row"><span><b>${esc((o&&o.order_number)||p.reference||'Pending')}</b><br><small>${esc(statusLabel(p.status))} · ${money(Number(p.amount))}<br>${esc(fmtDate(p.submitted_at))}</small></span></div><p class="muted">${items||'—'}</p><p class="meta">${addr?esc([addr.name,addr.phone,addr.line1,addr.city].filter(Boolean).join(' · ')) :''}${p.sender_account_name?' · Sender '+esc(p.sender_account_name):''}</p><div class="side">${p.receipt_path?`<button class="pill" onclick="inspectPaymentProof('${p.id}')">View proof</button>`:''}${p.status==='awaiting_verification'?`<button class="pill" onclick="reviewManualPayment('${p.id}','approve')">Approve</button><button class="pill" onclick="reviewManualPayment('${p.id}','reject')">Reject</button>`:''}</div></div>`}).join(''):'<div class="empty">No manual payments yet.</div>'}catch(e){el.textContent='Unable to load payment queue.'}}
async function reviewManualPayment(id,decision){decision=decision||'approve';if(decision==='approve'){const ref=prompt('Bank transaction reference (required to approve)');if(!ref)return;const notes=prompt('Admin notes (optional)')||'';try{await FashionMaisonSupabase.verifyManualPayment({payment_id:id,decision:'approve',bank_transaction_reference:ref,admin_notes:notes});loadManualPayments()}catch(e){alert('Payment could not be verified.')}}else{const reason=prompt('Rejection reason (required)');if(!reason)return;try{await FashionMaisonSupabase.verifyManualPayment({payment_id:id,decision:'reject',rejection_reason:reason});loadManualPayments()}catch(e){alert('Payment could not be rejected.')}}}async function inspectPaymentProof(id){try{const r=await FashionMaisonSupabase.invoke('payment-receipt-url',{payment_id:id});if(r&&r.url)window.open(r.url,'_blank','noopener');else alert('Proof is not available.')}catch(e){alert('Unable to open proof.')}}async function loadPaymentSettingsAdmin(){const el=document.getElementById('payment-settings-admin');if(!el)return;try{let rows=null;try{rows=await FashionMaisonSupabase.rest('/rest/v1/payment_settings?select=id,bank_name,account_name,account_number,payment_instructions,paystack_enabled,manual_transfer_enabled&store_id=is.null&limit=1')}catch(e){try{rows=await FashionMaisonSupabase.rest('/rest/v1/payment_settings?select=id,bank_name,account_name,account_number,payment_instructions&is_active=eq.true&limit=1')}catch(e2){rows=await FashionMaisonSupabase.rest('/rest/v1/payment_settings?select=id,bank_name,account_name,account_number,payment_instructions&limit=1')}}const s=rows&&rows[0]||{};el.innerHTML=`<div class="field"><label>Bank name</label><input id="ps-bank" value="${esc(s.bank_name||'')}"></div><div class="field"><label>Account name</label><input id="ps-name" value="${esc(s.account_name||'')}"></div><div class="field"><label>Account number</label><input id="ps-number" value="${esc(s.account_number||'')}"></div><div class="field"><label>Payment instructions</label><textarea id="ps-notes" rows="3">${esc(s.payment_instructions||s.instructions||'')}</textarea></div><div class="side"><label><input type="checkbox" id="ps-paystack" ${s.paystack_enabled!==false?'checked':''}> Paystack enabled</label><label><input type="checkbox" id="ps-manual" ${s.manual_transfer_enabled!==false?'checked':''}> Bank transfer enabled</label></div><button class="btn light" onclick="savePaymentSettings('${esc(s.id||'')}')">Save bank details</button>`}catch(e){el.textContent='Unable to load payment settings.'}}async function savePaymentSettings(id){const st=document.getElementById('admin-status');const record={bank_name:(document.getElementById('ps-bank')||{}).value||null,account_name:(document.getElementById('ps-name')||{}).value||null,account_number:(document.getElementById('ps-number')||{}).value||null,payment_instructions:(document.getElementById('ps-notes')||{}).value||null,paystack_enabled:!!(document.getElementById('ps-paystack')&&document.getElementById('ps-paystack').checked),manual_transfer_enabled:!!(document.getElementById('ps-manual')&&document.getElementById('ps-manual').checked)};try{if(id)await FashionMaisonSupabase.invoke('admin-catalog',{table:'payment_settings',operation:'update',id,record});else await FashionMaisonSupabase.invoke('admin-catalog',{table:'payment_settings',operation:'insert',record:Object.assign({store_id:null,currency:'NGN'},record)});if(st)st.textContent='Payment settings saved.';loadPaymentSettingsAdmin()}catch(e){try{const slim={bank_name:record.bank_name,account_name:record.account_name,account_number:record.account_number,payment_instructions:record.payment_instructions};if(id)await FashionMaisonSupabase.rest(`/rest/v1/payment_settings?id=eq.${encodeURIComponent(id)}`,{method:'PATCH',body:JSON.stringify(slim)});else throw e;if(st)st.textContent='Payment settings saved.';loadPaymentSettingsAdmin()}catch(e2){if(st)st.textContent='Unable to save payment settings.'}}}
async function saveHeroMerch(){const product=document.getElementById('hero-product').value;try{await FashionMaisonSupabase.saveMerchandising({section_key:'hero',hero_product_id:product,title:document.getElementById('hero-title').value,subtitle:document.getElementById('hero-subtitle').value,enabled:true,updated_by:null});document.getElementById('admin-status').textContent='Hero merchandising saved.'}catch(e){document.getElementById('admin-status').textContent='Unable to save merchandising.'}}
async function saveSectionMerch(key){const enabled=document.getElementById('enabled-'+key).checked;try{await FashionMaisonSupabase.saveMerchandising({section_key:key,enabled,product_ids:[]});document.getElementById('admin-status').textContent='Section saved.'}catch(e){document.getElementById('admin-status').textContent='Unable to save section.'}}
function footer(){return `<footer class="footer"><div class="logo">Fashion Maison<small>Fashion, discovered differently.</small></div><div class="muted contact-orbit">WE STYLE WITH EXOTIC, YOU SHINE.<br><br>No. 7 Usang Udo Street,<br>Opposite Akpana Ndewo Market,<br>Uyo, Akwa Ibom,<br>Nigeria<br><br><span class="contact-label">CONTACT DETAILS</span><br><span class="contact-type">PHONE</span> <a href="tel:08063936917">08063936917</a><br><span class="contact-type">WHATSAPP</span> <a href="https://wa.me/2348063936917" target="_blank" rel="noopener">08063936917</a><br><span class="contact-type">TIKTOK</span> <a href="https://www.tiktok.com/@Fashionmaison7" target="_blank" rel="noopener">@Fashionmaison7</a><br><span class="contact-type">EMAIL</span> <a href="mailto:Fashionmaison7@gmail.com">Fashionmaison7@gmail.com</a><br><br>© 2026 Fashion Maison</div></footer>`}
function add(id,mode){if(needsAccount()){gateAdd(id,mode);return}let p=products.find(x=>x.id==id);if(!p)return;const flags=purchaseFlags(p);if(flags.unavailable)return;let pre=mode==='preorder'||(mode!=='order'&&flags.preorder&&!flags.order);if(pre&&!flags.preorder)pre=false;if(!pre&&!flags.order){if(flags.preorder)pre=true;else return}const onProduct=/#\/product\//.test(location.hash||'');const size=onProduct?(selectedChoice('size')||((p.sizes&&p.sizes[0])||'One size')):((p.sizes&&p.sizes[0])||'One size');const color=onProduct?(selectedChoice('color')||((p.colors&&p.colors[0])||'House default')):((p.colors&&p.colors[0])||'House default');const v=findVariant(p,size,color);const key=makeKey(p.id,size,color,pre);const price=unitPrice(p,pre);let i=cart.find(x=>itemKey(x)===key);if(i)i.qty++;else cart.push({id:p.id,key,name:p.name,price,qty:1,cat:p.cat,status:p.status,size,color,variant_id:v&&v.id||null,is_preorder:!!pre,img:p.img,expected_unit_price:price,expected_availability:p.expected_availability||null});if(pre&&p.pre_order_max_qty){const line=cart.find(x=>itemKey(x)===key);if(line&&line.qty>Number(p.pre_order_max_qty))line.qty=Number(p.pre_order_max_qty)}save();render();}
function togglePayment(v){const el=document.getElementById('bank-transfer-info');if(el)el.classList.toggle('hidden',v!=='manual_transfer')}
function change(id,n){let i=cart.find(x=>itemKey(x)==id);if(!i)return;i.qty+=n;if(i.qty<1)cart=cart.filter(x=>itemKey(x)!=id);save();render()} function removeItem(id){cart=cart.filter(x=>itemKey(x)!=id);save();render()} function setFilter(x){filter=x;render()} function search(x){query=x;location.hash='#/shop';render()} function clearSearch(){query='';render()} function beginPayment(){const form=document.querySelector('.checkout form');if(form){form.requestSubmit?form.requestSubmit():placeOrder({preventDefault(){}});return}document.querySelector('main').innerHTML='<div class="empty"><div class="eyebrow">Secure payment unavailable</div><h1 class="serif">Payments temporarily unavailable.</h1><p>Your order has not been placed and no payment was taken. Please try again when secure Paystack configuration is available.</p><button class="btn" onclick="location.hash=\'#/cart\'">Return to bag</button></div>'}function updateCheckoutFee(){const sel=document.getElementById('co-delivery');const feeEl=document.getElementById('co-fee');if(!sel||!feeEl)return;const opt=sel.selectedOptions&&sel.selectedOptions[0];const fee=opt?Number(opt.getAttribute('data-fee')||0):0;feeEl.textContent=fee?money(fee):'Free'}async function initCheckout(){if(!document.getElementById('co-delivery'))return;try{const rows=await FashionMaisonSupabase.rest('/rest/v1/delivery_methods?select=key,label,fee,active,sort_order&active=eq.true&order=sort_order.asc');const sel=document.getElementById('co-delivery');if(sel&&rows&&rows.length){sel.innerHTML=rows.map(d=>`<option value="${esc(d.key)}" data-fee="${Number(d.fee)||0}">${esc(d.label)} — ${Number(d.fee)?money(Number(d.fee)):'Free'}</option>`).join('');sel.onchange=updateCheckoutFee;updateCheckoutFee()}}catch(e){}try{const pay=await FashionMaisonSupabase.paymentSettings();const box=document.getElementById('bank-transfer-info');const method=document.getElementById('payment-method');if(method&&pay){if(pay.paystack_enabled===false){const o=[...method.options].find(x=>x.value==='paystack');if(o)o.remove()}if(pay.manual_transfer_enabled===false){const o=[...method.options].find(x=>x.value==='manual_transfer');if(o)o.remove()}if(!method.value&&method.options.length)method.value=method.options[0].value}if(box){if(pay&&(pay.bank_name||pay.account_number)){box.innerHTML=`<b>Transfer to this account</b><div class="row"><span>Bank</span><span>${esc(pay.bank_name||'')}</span></div><div class="row"><span>Account name</span><span>${esc(pay.account_name||'')}</span></div><div class="row"><span>Account number</span><span>${esc(pay.account_number||'')}</span></div>${pay.payment_instructions?`<p class="muted">${esc(pay.payment_instructions)}</p>`:''}<small class="muted">Place the order first, then upload proof of payment. Approval is never automatic.</small>`}else{box.innerHTML='Bank transfer payment is not currently configured.<br><small class="muted">No payment has been created.</small>'}}togglePayment(method&&method.value)}catch(e){const box=document.getElementById('bank-transfer-info');if(box)box.innerHTML='Bank transfer payment is not currently configured.<br><small class="muted">No payment has been created.</small>'}}function refreshCartAvailability(){const kept=[];const dropped=[];for(const i of cart){const live=products.find(p=>p.id==i.id);if(!live){dropped.push(i.name||'A piece');continue}const flags=purchaseFlags(live);if(flags.unavailable||(i.is_preorder&&!flags.preorder)||(!i.is_preorder&&!flags.order&&!flags.preorder)){dropped.push(live.name);continue}const price=unitPrice(live,!!i.is_preorder);kept.push(Object.assign({},i,{name:live.name,price,expected_unit_price:price,status:live.status,expected_availability:live.expected_availability||i.expected_availability||null,variant_id:i.variant_id||((findVariant(live,i.size,i.color)||{}).id)||null}))}cart=kept;save();if(dropped.length)return {ok:false,message:'Some pieces are no longer available: '+dropped.join(', ')+'. They were removed from your bag.'};if(!cart.length)return {ok:false,message:'Your bag is empty.'};return {ok:true}}async function placeOrder(e){if(e&&e.preventDefault)e.preventDefault();const st=document.getElementById('co-status');const say=m=>{if(st)st.textContent=m};if(needsAccount()){location.hash='#/account';return}if(!window.FashionMaisonSupabase||!FashionMaisonSupabase.configured){say('Secure checkout is not configured on this deployment.');beginPayment();return}const check=refreshCartAvailability();if(!check.ok){say(check.message);render();return}const method=(document.getElementById('payment-method')||{}).value||'paystack';const delivery=(document.getElementById('co-delivery')||{}).value||'store_pickup';const address={name:(document.getElementById('co-name')||{}).value||'',email:(document.getElementById('co-email')||{}).value||'',phone:(document.getElementById('co-phone')||{}).value||'',line1:(document.getElementById('co-line1')||{}).value||'',city:(document.getElementById('co-city')||{}).value||'',state:(document.getElementById('co-state')||{}).value||''};if(!address.name||!address.phone||!address.line1||!address.city){say('Please complete your delivery details.');return}const items=cart.map(i=>({product_id:i.id,variant_id:i.variant_id||null,quantity:i.qty,expected_unit_price:i.expected_unit_price||i.price,is_preorder:!!i.is_preorder}));let idem=sessionStorage.getItem('fm-idem');if(!idem){idem=(crypto.randomUUID&&crypto.randomUUID())||('fm'+Date.now()+Math.random());sessionStorage.setItem('fm-idem',idem)}say('Placing your order…');try{const r=await FashionMaisonSupabase.invoke('create-order',{items,delivery_method:delivery,payment_method:method==='paystack'?'paystack':'manual_transfer',idempotency_key:idem,address});if(!r||!(r.ok||r.order)){say((r&&(r.message||r.code))||'Unable to create order.');return}const order=r.order||r;sessionStorage.removeItem('fm-idem');cart=[];save();sessionStorage.setItem('fm-open-order',JSON.stringify(order));if(method==='paystack'){say('Starting Paystack…');const pay=await FashionMaisonSupabase.invoke('initialize-paystack',{order_id:order.order_id||order.id,email:address.email,redirect_url:location.origin+(location.pathname||'/')+'#/checkout/return'});if(pay&&pay.authorization_url){location.href=pay.authorization_url;return}say((pay&&pay.message)||'Paystack is not available. Your order is reserved — try bank transfer from your account.');location.hash='#/account';return}location.hash='#/pay/'+(order.order_id||order.id)}catch(err){say(err.message||'Unable to create order.')}}async function initPayPage(orderId){const st=document.getElementById('pay-status');const body=document.getElementById('pay-body');if(!st||!body)return;try{const rows=await FashionMaisonSupabase.rest(`/rest/v1/orders?select=id,order_number,total,status,delivery_method,payments(id,status,provider,receipt_path,rejection_reason),order_items(product_name,quantity,unit_price,is_preorder)&id=eq.${encodeURIComponent(orderId)}&limit=1`);const o=rows&&rows[0];if(!o){st.textContent='Order not found.';return}const pay=Array.isArray(o.payments)?o.payments[0]:o.payments;if(['paid','pre-order','processing','ready','shipped','delivered'].includes(o.status)||(pay&&pay.status==='successful')){st.textContent='Payment verified. Thank you.';body.innerHTML=`<p>${esc(o.order_number)} · ${money(Number(o.total))}</p><button class="btn" onclick="location.hash='#/account'">View orders</button>`;return}if(o.status==='pending_manual_verification'||(pay&&pay.status==='awaiting_verification')){st.textContent='Payment proof uploaded — awaiting verification.';body.innerHTML=`<p>${esc(o.order_number)} · ${money(Number(o.total))}</p><p class="muted">Our team will review your transfer. This does not approve the order by itself.</p><button class="btn light" onclick="location.hash='#/account'">Account</button>`;return}const settings=await FashionMaisonSupabase.paymentSettings();const rejected=pay&&pay.status==='rejected';st.textContent=rejected?('Payment needs attention'+(pay.rejection_reason?': '+pay.rejection_reason:'')):'Transfer the order total and upload proof.';if(!settings||!(settings.bank_name||settings.account_number)){body.innerHTML='<p class="muted">Bank transfer payment is not currently configured.</p>';return}body.innerHTML=`<div class="summary"><b>${esc(o.order_number)}</b><div class="row"><span>Amount</span><b>${money(Number(o.total))}</b></div><div class="row"><span>Bank</span><span>${esc(settings.bank_name)}</span></div><div class="row"><span>Account name</span><span>${esc(settings.account_name)}</span></div><div class="row"><span>Account number</span><span>${esc(settings.account_number)}</span></div>${settings.payment_instructions?`<p class="muted">${esc(settings.payment_instructions)}</p>`:''}</div><div class="field"><label>Your sender name (optional)</label><input id="proof-sender-name" placeholder="Name on the transferring account"></div><div class="field"><label>Your account number (optional)</label><input id="proof-sender-number" placeholder="Account number used"></div><div class="field"><label>Proof of payment (JPEG, PNG, WebP or PDF)</label><input id="proof-file" type="file" accept="image/jpeg,image/png,image/webp,application/pdf"></div><button class="btn" onclick="submitProof('${esc(o.id)}')">Upload proof</button>`}catch(e){st.textContent='Unable to load this payment.'}}function fmSafeReceiptName(name){const base=String(name||'receipt').split(/[/\\]/).pop();const dot=base.lastIndexOf('.');const ext=(dot>=0?base.slice(dot):'').toLowerCase();const stem=((dot>=0?base.slice(0,dot):base).replace(/[^a-zA-Z0-9._-]+/g,'-').replace(/^-+|-+$/g,'').slice(0,80))||'receipt';return stem+(['.jpg','.jpeg','.png','.webp','.pdf'].includes(ext)?ext:'.jpg')}async function submitProof(orderId){const st=document.getElementById('pay-status');const file=document.getElementById('proof-file')&&document.getElementById('proof-file').files&&document.getElementById('proof-file').files[0];if(!file){if(st)st.textContent='Choose a receipt image or PDF first.';return}if(!session||!session.id){location.hash='#/account';return}const okType=/^(image\/(jpeg|png|webp)|application\/pdf)$/.test(file.type);if(!okType||file.size>10485760){if(st)st.textContent='Use a JPEG, PNG, WebP or PDF up to 10MB.';return}try{if(st)st.textContent='Uploading proof…';const path=`receipts/${session.id}/${orderId}/${Date.now()}-${fmSafeReceiptName(file.name)}`;await FashionMaisonSupabase.uploadPaymentReceipt(path,file);await FashionMaisonSupabase.submitManualPayment({order_id:orderId,receipt_path:path,sender_account_name:(document.getElementById('proof-sender-name')||{}).value||null,sender_account_number:(document.getElementById('proof-sender-number')||{}).value||null});if(st)st.textContent='Payment proof uploaded — awaiting verification.';initPayPage(orderId)}catch(e){if(st)st.textContent=e.message||'Could not submit the transfer receipt.'}}async function initCheckoutReturn(){const st=document.getElementById('pay-status');const raw=(location.hash||'').split('?')[1]||'';const q=new URLSearchParams(raw+'&'+(location.search||'').replace(/^\?/,''));const ref=q.get('reference')||q.get('trxref');if(!st)return;if(!ref){st.textContent='No payment reference was returned.';return}try{st.textContent='Verifying with Paystack…';const r=await FashionMaisonSupabase.invoke('verify-paystack',{reference:ref});if(r&&r.ok){st.innerHTML='Payment verified. Thank you.<br><br><button class="btn" onclick="location.hash=\'#/account\'">View your orders</button>'}else{st.textContent=(r&&(r.message||r.code))||'Paystack has not confirmed this payment yet. Your order is not marked paid from this page alone.'}}catch(e){st.textContent='Unable to verify this payment.'}}
async function loadLiveProducts(){if(!window.FashionMaisonSupabase?.configured)return;try{const r=await window.FashionMaisonSupabase.rest('/rest/v1/products?select=*,product_images(*),product_variants(*,inventory(*)),categories(name)&published=eq.true&order=created_at.desc');if(Array.isArray(r))products=r.map(x=>{const imgs=catalogImageUrls(x);const attrs=(x.attributes&&typeof x.attributes==='object'&&!Array.isArray(x.attributes))?x.attributes:{};const cat=(x.categories&&(x.categories.name||(Array.isArray(x.categories)&&x.categories[0]&&x.categories[0].name)))||attrs.house_category||'Fashion';const variants=x.product_variants||[];return {id:x.id,name:x.name,price:Number(x.base_price||x.price||0),cat,status:x.status||'AVAILABLE',sizes:variants.map(v=>v.size).filter(Boolean),colors:variants.map(v=>v.color).filter(Boolean),variants,imgs,img:imgs[0]||'',desc:x.description||'',caption:String(attrs.caption||attrs.short_caption||'').trim(),brand:x.brand||attrs.brand||'',category_id:x.category_id||null,attributes:attrs,pre_order_price:x.pre_order_price!=null?Number(x.pre_order_price):null,pre_order_closes_at:x.pre_order_closes_at||null,expected_availability:x.expected_availability||null,order_enabled:x.order_enabled,pre_order_enabled:x.pre_order_enabled,pre_order_notes:x.pre_order_notes||attrs.pre_order_notes||'',pre_order_max_qty:x.pre_order_max_qty!=null?Number(x.pre_order_max_qty):null,product_type:x.product_type||'ready_made'}})}catch(e){console.warn('Live catalog unavailable',e)}try{const m=await window.FashionMaisonSupabase.homepageMerchandising();if(Array.isArray(m))merchandising=m}catch(e){console.warn('Merchandising unavailable',e)}render()}
function render(){let raw=location.hash||'#/';let h=raw.split('?')[0];const q=new URLSearchParams((raw.split('?')[1]||'')+'&'+(location.search||'').replace(/^\?/,''));let content;if(h==='#/' )content=home();else if(h.startsWith('#/shop'))content=shop();else if(h==='#/cart')content=cartPage();else if(h==='#/checkout/return'||(h==='#/checkout'&&q.get('reference')))content=checkoutReturnPage();else if(h==='#/checkout')content=checkout();else if(h.startsWith('#/pay/'))content=payPage(h.split('/')[2]);else if(h==='#/account'||h==='#/login')content=accountPage();else if(h==='#/merchant')content=merchant();else if(h.startsWith('#/product/'))content=product(h.split('/')[2]);else content=home();document.getElementById('app').innerHTML=content;window.FashionMaisonMotion?.init();if(h==='#/merchant')setTimeout(initMerchAdmin,0);if(h==='#/account'||h==='#/login')setTimeout(initAccount,0);if(h==='#/checkout'&&!q.get('reference'))setTimeout(initCheckout,0);if(h==='#/checkout/return'||(h==='#/checkout'&&q.get('reference')))setTimeout(initCheckoutReturn,0);if(h.startsWith('#/pay/'))setTimeout(()=>initPayPage(h.split('/')[2]),0)}window.addEventListener('hashchange',render);render();
async function loadSession(){session=null;if(!window.FashionMaisonSupabase||!FashionMaisonSupabase.configured)return;try{if(!sessionStorage.getItem('fm-access-token'))return;const u=await FashionMaisonSupabase.getUser();if(u&&u.id)session={id:u.id,email:u.email||''}}catch(e){session=null}}
async function boot(){await Promise.all([loadSession(),loadLiveProducts(),loadFxRate()]);const pending=sessionStorage.getItem('fm-pending-add');const mode=sessionStorage.getItem('fm-pending-mode');if(session&&pending){sessionStorage.removeItem('fm-pending-add');sessionStorage.removeItem('fm-pending-mode');add(pending,mode||undefined);if(!(location.hash||'').startsWith('#/cart'))location.hash='#/cart'}}
async function loadFxRate(){if(!window.FashionMaisonSupabase||!FashionMaisonSupabase.configured)return;try{const rows=await FashionMaisonSupabase.rest('/rest/v1/current_usd_ngn_rate?select=rate&limit=1');if(rows&&rows[0]&&rows[0].rate){window.FM_FX_RATE=Number(rows[0].rate);localStorage.setItem('fm-fx-rate',String(rows[0].rate))}}catch(e){}}
boot();if((location.hash||'').startsWith('#/merchant'))setTimeout(initMerchAdmin,0);if((location.hash||'')==='#/account'||(location.hash||'')==='#/login')setTimeout(initAccount,0);if('serviceWorker'in navigator)navigator.serviceWorker.register('sw.js');